"""Original, statically authored Japanese mock items with Bengali review.

Question order and option order are deterministic. Passages are authored here;
the browser never manufactures questions or fills a shortage with repeats.
"""
import hashlib,json,random,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
BANK={l:[] for l in ('n5','n4','n3')}
COUNTS={}
def add(level,category,kind,prompt,options,answer,bn,reason,passage=None,reading_kind=None):
    key=(level,category,kind,reading_kind)
    COUNTS[key]=COUNTS.get(key,0)+1
    tag=reading_kind or {'文の組み立て':'star','文章文法':'text','文法形式':'form','語彙':'vocab','表記':'spelling','読解':'reading'}[kind]
    qid=f'aponar-{level}-{category}-{tag}-{COUNTS[key]:03}'
    order=list(range(len(options)))
    random.Random(int(hashlib.sha256(qid.encode()).hexdigest()[:12],16)).shuffle(order)
    assert len(set(options))==len(options),qid
    q={'id':qid,'group':'listening' if category=='listening' else ('reading' if category=='reading' else 'language') if level=='n3' else 'knowledgeReading',
       'category':category,'kind':kind,'prompt':prompt,'options':[options[i] for i in order],'answer':order.index(answer),
       'provenance':'aponar-original','sourceCategory':category,'sourceUrl':'/mock-content-notes.html','sourceQuestion':COUNTS[key],'fixedOptions':True,
       'review':{'answerBn':bn,'explanationBn':reason}}
    if passage:q['passage']=passage
    if reading_kind:q['readingKind']=reading_kind
    assert len(reason)>=40,qid
    BANK[level].append(q)
    return q

def star(level,prefix,chunks,suffix,bn,third):
    assert len(chunks)==4
    add(level,'grammar','文の組み立て',prefix+' _______ _______ …★… _______ '+suffix,chunks,2,third,
        'সঠিক ক্রম '+ ' → '.join(chunks)+'। পুরো বাক্যের অর্থ: '+bn+' তাই তারকার তৃতীয় স্থানে '+chunks[2]+' বসবে।')

