for prompt,opts,bn,reason in [
('この仕事は、経験がない人に（　　　）難しいと思う。',['とって','よって','つれて','かけて'],'যাঁদের অভিজ্ঞতা নেই তাঁদের জন্য','にとって কোনো ব্যক্তির দৃষ্টিতে মূল্যায়ন। অভিজ্ঞতাহীন ব্যক্তির কাছে কাজটি কঠিন বলা হচ্ছে; কারণ বা পরিবর্তনের সম্পর্ক নয়।'),
('祖父は八十歳の（　　　）、毎日五キロ歩く。',['わりに','ところに','最中に','せいで'],'বয়সের তুলনায়','名詞のわりに প্রত্যাশার বিপরীত তুলনা। আশি বছর বয়সের তুলনায় দাদার প্রতিদিন পাঁচ কিলোমিটার হাঁটা বিস্ময়কর।'),
('詳しい説明を聞いた（　　　）、申し込むかどうか決めたい。',['上で','ついでに','ままに','一方で'],'শুনে তারপর','た上で প্রয়োজনীয় প্রথম ধাপ শেষ করে পরের সিদ্ধান্ত। বিস্তারিত ব্যাখ্যা শুনে তারপর আবেদন করবেন কি না ঠিক করবেন।'),
('休みの日は料理をする（　　　）、写真を撮りに出かける。',['かわりに','ためには','ところを','最中には'],'রান্নার পরিবর্তে','かわりに এক কাজের বদলে আরেক কাজ বোঝায়। ছুটির দিনে রান্না না করে ছবি তুলতে বেরোনোর বিকল্প কাজ।'),
('努力したからといって、必ず成功する（　　　）。',['わけではない','に違いない','つもりだった','ことにした'],'সবসময় সফল হয় এমন নয়','からといって〜わけではない একটি কারণ থেকে নিশ্চিত ফল ধরে নেওয়া অস্বীকার। চেষ্টা প্রয়োজনীয় হলেও সাফল্যের নিশ্চয়তা নেই।'),
('この機械は、ボタンを押すと自動で止まる（　　　）。',['ようになっている','ことにしている','つもりでいる','ようとしている'],'এমন ব্যবস্থা আছে','ようになっている যন্ত্রের নকশা বা কার্যব্যবস্থা বোঝায়। বোতাম চাপলে নিজে থামার ব্যবস্থা, ব্যক্তির সিদ্ধান্ত নয়।'),
]:add('n3','grammar','文法形式',prompt,opts,0,bn,reason)
add('n3','kanji','表記','先生が旅行の計画を<span style="text-decoration:underline">ていあん</span>しました。',['提案','定安','体案','低暗'],0,'প্রস্তাব','ていあん-এর সঠিক লিখিত রূপ 提案। 提 তুলে ধরা এবং 案 পরিকল্পনা; ভ্রমণের পরিকল্পনা প্রস্তাব করার অর্থে এই শব্দটি হয়।')
add('n3','kanji','表記','新しい仕事に<span style="text-decoration:underline">ちょうせん</span>します。',['挑戦','朝線','長選','調先'],0,'চ্যালেঞ্জ নেওয়া','ちょうせん-এর বানান 挑戦, নতুন কঠিন কাজে চেষ্টা বা চ্যালেঞ্জ নেওয়া। একই উচ্চারণের মতো দেখানো ভুল বানানগুলো অর্থপূর্ণ নয়।')

add('n4','kanji','表記','朝、駅の前で友達を<span style="text-decoration:underline">まちました</span>。',['待ちました','持ちました','町ました','時ちました'],0,'অপেক্ষা করেছি','まつ অপেক্ষা করা ক্রিয়ার কানজি 待つ। অতীত ভদ্র রূপ 待ちました; 持つ হাতে রাখা বা বহন করা আলাদা ক্রিয়া।')
add('n4','kanji','表記','この<span style="text-decoration:underline">しゃしん</span>を見てください。',['写真','社真','写新','者親'],0,'আলোকচিত্র','しゃしん-এর লিখিত রূপ 写真। 写 ছবিতে ধারণ করা এবং 真 বাস্তব রূপের ধারণা; অন্য বিকল্পগুলো এই শব্দের বানান নয়।')

PARAPHRASE=[
('会議の日を<span style="text-decoration:underline">延期した</span>。','会議の日を予定より後にした。',['予定より前にした。','会議をすべて中止した。','会議の場所を変えた。'],'নির্ধারিত সময়ের পরে সরিয়েছি','延期 করা মানে সময় পিছিয়ে দেওয়া। বাতিল বা আগে করা আলাদা সিদ্ধান্ত; সভার স্থান বদলও সময় পরিবর্তন নয়।'),
('彼は<span style="text-decoration:underline">めったに</span>怒らない。','怒ることがほとんどない。',['毎日よく怒る。','怒るのを楽しむ。','昨日だけ怒った。'],'প্রায় কখনও রাগ করেন না','めったに + নঞর্থক ক্রিয়া খুব কম ঘটে বোঝায়। কখনও রাগ হয় না এমন চূড়ান্ত দাবি নয়, প্রায় হয় না।'),
('この資料は<span style="text-decoration:underline">正確</span>だ。','この資料には間違いがない。',['この資料は長い。','この資料は古い。','この資料は高い。'],'সঠিক ও ভুলহীন','正確 তথ্যের যথার্থতা। আকার, বয়স বা দামের মূল্যায়ন নয়; 間違いがない কাছের অর্থ।'),
('荷物を<span style="text-decoration:underline">まとめた</span>。','荷物を一つに集めた。',['荷物を全部捨てた。','荷物を借りた。','荷物を忘れた。'],'এক জায়গায় একত্র করেছি','まとめる ছড়িয়ে থাকা জিনিস একত্র করা বা গোছানো। ফেলে দেওয়া বা ভুলে যাওয়ার অর্থ নয়।'),
('その話は<span style="text-decoration:underline">意外</span>だった。','思っていたことと違っていた。',['前からよく知っていた。','すぐに忘れた。','誰にも話さなかった。'],'প্রত্যাশার থেকে আলাদা','意外 অনুমান বা প্রত্যাশার বাইরে হওয়া। আগেই জানা বা চুপ করে থাকার সঙ্গে শব্দটির সম্পর্ক নেই।'),
('作業を<span style="text-decoration:underline">続けた</span>。','作業をやめずにした。',['作業を始める前だった。','作業を忘れた。','作業を他人に頼んだ。'],'কাজ থামাইনি','続ける ইতিমধ্যে শুরু হওয়া কাজ চালিয়ে যাওয়া। তাই やめずに করা অর্থের সঙ্গে মেলে।'),
('今日は<span style="text-decoration:underline">余裕</span>がある。','今日は時間や気持ちにゆとりがある。',['今日は忙しくて何もできない。','今日は予定が分からない。','今日は財布をなくした。'],'সময় বা মানসিক অবকাশ আছে','余裕 প্রয়োজনের অতিরিক্ত সুযোগ বা স্বচ্ছন্দ অবস্থা। এখানে সময় ও মন শান্ত থাকার মতোゆとり সমার্থক।'),
('その道は<span style="text-decoration:underline">混雑</span>している。','その道は人や車でいっぱいだ。',['その道は短い。','その道は暗い。','その道は新しい。'],'লোক বা গাড়িতে ভরা','混雑 মানুষ বা যানবাহনের ভিড়। রাস্তার দৈর্ঘ্য, আলো বা নতুন হওয়ার কথা বোঝায় না।'),
('返事を<span style="text-decoration:underline">保留</span>した。','今すぐ返事を決めなかった。',['返事をすぐに出した。','質問を忘れた。','答えを全員に知らせた。'],'উত্তরের সিদ্ধান্ত স্থগিত রেখেছি','保留 প্রয়োজনীয় সিদ্ধান্ত আপাতত না নিয়ে রেখে দেওয়া। সম্পূর্ণ বাতিল না করে পরে সিদ্ধান্ত নেওয়ার সুযোগ থাকে।'),
('料金を<span style="text-decoration:underline">確認</span>した。','料金がいくらか確かめた。',['料金を高くした。','料金を払わなかった。','料金を借りた。'],'দাম কত তা যাচাই করেছি','確認 মানে 確かめる, ঠিক কী তা পরীক্ষা করে নিশ্চিত হওয়া। দাম পরিবর্তন বা পরিশোধের কাজ নয়।'),
('旅行を<span style="text-decoration:underline">断念</span>した。','旅行をするのをあきらめた。',['旅行を予約した。','旅行から帰った。','旅行先を増やした。'],'ভ্রমণের আশা ছেড়েছি','断念 পরিকল্পনা বা আকাঙ্ক্ষা পূরণ অসম্ভব মনে করে ছেড়ে দেওয়া। ভ্রমণ বুক করা বা ফিরে আসা বিপরীত ঘটনা।'),
('その結果には<span style="text-decoration:underline">納得</span>した。','その結果を理解して受け入れた。',['その結果を見なかった。','その結果が怖かった。','その結果を変えた。'],'ফল বুঝে মেনে নিয়েছি','納得 যুক্তি বা কারণ বুঝে সন্তুষ্টভাবে গ্রহণ করা। শুধু ফল দেখা বা বদলানো নয়।'),
('彼女は<span style="text-decoration:underline">慎重</span>に答えた。','よく考えて、注意して答えた。',['何も考えずに答えた。','大声で答えた。','答えるのをやめた。'],'ভেবে সতর্কভাবে উত্তর দিয়েছেন','慎重 অসতর্ক না হয়ে ভালোভাবে ভেবে কাজ করা। শব্দটি কণ্ঠের জোর নয়, সিদ্ধান্তের সতর্কতা বোঝায়।'),
('この商品は<span style="text-decoration:underline">売り切れ</span>だ。','この商品は全部売れて、残っていない。',['まだ販売していない。','値段が安くなった。','全部壊れている。'],'সব বিক্রি হয়ে গেছে','売り切れ বিক্রির জন্য রাখা মজুত সম্পূর্ণ শেষ। দোকান বন্ধ বা পণ্য নষ্ট হওয়া বোঝায় না।'),
('彼を<span style="text-decoration:underline">信頼</span>している。','彼は頼りになると思っている。',['彼が嫌いだと思っている。','彼を知らない。','彼より背が高い。'],'ভরসাযোগ্য মনে করি','信頼 অন্য ব্যক্তির যোগ্যতা বা সততার ওপর ভরসা করা। ব্যক্তিগত অপছন্দ বা শারীরিক তুলনার সঙ্গে সম্পর্ক নেই।'),
('説明は<span style="text-decoration:underline">簡潔</span>だった。','短く、必要なことがまとまっていた。',['長くて何度も同じ話をした。','内容が全部間違っていた。','声が小さく聞こえなかった。'],'সংক্ষিপ্ত ও প্রয়োজনীয় বিষয় গুছানো','簡潔 শুধু ছোট নয়, অপ্রয়োজনীয় অংশ ছাড়া প্রয়োজনীয় কথা পরিষ্কারভাবে বলা। ভুল তথ্য বা দুর্বল কণ্ঠ বোঝায় না।'),
('道具を<span style="text-decoration:underline">貸し出す</span>。','道具を一定の間ほかの人に使わせる。',['道具をほかの人から借りる。','道具を永久に捨てる。','道具を作り直す。'],'সীমিত সময় অন্যকে ব্যবহার করতে দেওয়া','貸し出す নিজের বা প্রতিষ্ঠানের জিনিস অন্যকে ধার দেওয়া। 借りる ধার নেওয়ার বিপরীত দিক।'),
('予定は<span style="text-decoration:underline">未定</span>だ。','予定はまだ決まっていない。',['予定はなくなった。','予定は昨日終わった。','予定は変えられない。'],'এখনও ঠিক হয়নি','未定 এখনো সিদ্ধান্ত না হওয়া।取消 বাতিল বা終了 সম্পন্ন হওয়া থেকে আলাদা।'),
('その説明は<span style="text-decoration:underline">具体的</span>だ。','例や数字を使って、はっきり示している。',['何も詳しく言っていない。','誰も理解できない。','昔の話ばかりしている。'],'উদাহরণ ও সংখ্যা দিয়ে স্পষ্ট','具体的বিমূর্ত না হয়ে পরিষ্কার উদাহরণ বা তথ্য দিয়ে বোঝানো। অস্পষ্ট বলা তার বিপরীত।'),
('彼は<span style="text-decoration:underline">偶然</span>そこにいた。','特に計画していないのに、そこにいた。',['前から決めて待っていた。','毎日同じ時刻に来ていた。','必ず来る約束だった。'],'পরিকল্পনা ছাড়াই ঘটনাক্রমে ছিলেন','偶然 আগে ইচ্ছাকৃত পরিকল্পনা ছাড়া ঘটনা মিলিয়ে যাওয়া। পূর্বনির্ধারিত সাক্ষাৎ বা নিয়মিত অভ্যাস নয়।'),
('仕事を<span style="text-decoration:underline">分担</span>した。','仕事を分けて、それぞれ受け持った。',['一人が全部やった。','仕事をすべてやめた。','仕事の場所を変えた。'],'কাজ ভাগ করে নিয়েছি','分担 একটি পুরো কাজ কয়েকজনের মধ্যে দায়িত্ব হিসেবে ভাগ করা। একা সব করা শব্দটির বিপরীত।'),
('時間を<span style="text-decoration:underline">短縮</span>した。','かかる時間を短くした。',['かかる時間を長くした。','時間を調べなかった。','始まる日を忘れた。'],'লাগা সময় কমিয়েছি','短縮 দৈর্ঘ্য বা সময় ছোট করা।時間を短くする এই বাক্যে সরাসরি সমার্থক।'),
]
for p,r,w,b,e in PARAPHRASE:vocab('n3','意味が最も近いものを選んでください。'+p,[r]+w,b,e)

USAGE=[
('改善','利用者の意見を聞いて、サービスを改善した。',['先生の名前を改善して呼んだ。','昼ご飯を改善で食べた。','電車を改善に乗った。'],'সেবার মান উন্নত করেছি','改善 খারাপ বা অপর্যাপ্ত অবস্থা ভালো করা। সেবার ব্যবস্থাকে উন্নত করা অর্থে স্বাভাবিক কর্ম; নাম বা যানবাহনের সঙ্গে দেওয়া ব্যবহার ভুল।'),
('遠慮','おかわりを勧められたが、遠慮した。',['駅まで遠慮を運転した。','紙を遠慮で切った。','昨日は遠慮に雨だった。'],'সংকোচে আর নিতে চাইনি','遠慮 অন্যের প্রতি বিবেচনা বা সংকোচে কিছু গ্রহণ না করা।追加 খাবারের প্রস্তাব বিনয়ে না নেওয়া যথাযথ ব্যবহার।'),
('集中','周りが静かなので、勉強に集中できる。',['靴を集中して履いた。','駅を集中で歩いた。','財布に集中を入れた。'],'পড়ায় মনোযোগ দিতে পারি','集中 মনোযোগকে একটি কাজের দিকে একত্র করা, 勉強に集中する প্রচলিত। অন্যান্য বাক্যে শব্দটির সম্পর্ক ভুল।'),
('相談','進学について先生に相談した。',['ご飯を相談して焼いた。','雨が相談を降った。','服を相談に着た。'],'পড়ার পরিকল্পনা নিয়ে পরামর্শ করেছি','相談 কোনো সমস্যার বিষয় বা সিদ্ধান্ত নিয়ে অন্যের মত নেওয়া। 先生に相談する এবং বিষয়について স্বাভাবিক ব্যবহার।'),
('比較','二つの商品の値段を比較した。',['比較の水を飲んだ。','駅で比較を乗った。','昨日を比較に忘れた。'],'দুটি পণ্যের দাম তুলনা করেছি','比較 দুই বা বেশি বিষয়ের মিল-অমিল বিচার। পণ্যের দামを比較する যথাযথ কর্ম।'),
('参加','地域の清掃活動に参加した。',['お茶を参加して飲んだ。','靴の参加を洗った。','紙に参加を泳いだ。'],'পরিষ্কার অভিযানে অংশ নিয়েছি','参加 কোনো আয়োজন বা কার্যক্রমে যোগ দেওয়া। 活動に参加する-তে に অংশগ্রহণের ক্ষেত্র।'),
('準備','発表の前に、資料を準備した。',['昨日の雨を準備で降った。','昼寝を準備に読んだ。','机が準備を走った。'],'উপস্থাপনার কাগজ প্রস্তুত করেছি','準備 ভবিষ্যৎ কাজের প্রয়োজনীয় জিনিস বা অবস্থা আগে তৈরি করা। বক্তব্যের আগে資料প্রস্তুত করা যথার্থ।'),
('協力','みんなで協力して、会場を片付けた。',['電車を協力で乗った。','魚が協力を焼いた。','傘に協力を晴れた。'],'একসঙ্গে সহায়তা করে জায়গা গুছিয়েছি','協力একটি উদ্দেশ্যে বহুজনের সাহায্য বা যৌথ কাজ। সবাই মিলে আয়োজনের স্থান গোছানোয় শব্দটির সঠিক অর্থ।'),
('確認','送信する前に、メールの内容を確認した。',['確認を昼ご飯で食べた。','道が確認を踊った。','靴を確認に眠った。'],'পাঠানোর আগে ইমেইল যাচাই করেছি','確認 তথ্য ঠিক আছে কি না নিশ্চিত করা। পাঠানোর আগে বিষয়বস্তু দেখা স্বাভাবিক; অন্য বাক্যে কর্মের অর্থ নেই।'),
('連続','三日連続で雨が降っている。',['机の連続を借りた。','昼ご飯を連続に着た。','電車が連続を食べた。'],'টানা তিন দিন বৃষ্টি হচ্ছে','連続 বিরতি ছাড়া ধারাবাহিক ঘটনা। 三日連続で তিন দিন একটানা বোঝায়।'),
('節約','電気をこまめに消して、電気代を節約する。',['友達を節約で会った。','公園が節約を泳いだ。','紙を節約に眠った。'],'বিদ্যুতের খরচ সাশ্রয় করি','節約 অপ্রয়োজনীয় ব্যবহার বা খরচ কমানো। বিদ্যুতের খরচを節約する শব্দটির যথাযথ ব্যবহার।'),
('支える','家族が私の留学を支えてくれた。',['名前を支えて呼んだ。','朝ご飯を支えで食べた。','昨日を支えて晴れた。'],'পরিবার পড়াশোনায় সহায়তা করেছে','支えるশারীরিকভাবে ধরে রাখা ছাড়াও সহায়তা করে কোনো কাজ চালাতে সাহায্য করা।留学কে পরিবারের সহায়তা অর্থে স্বাভাবিক।'),
('断る','都合が悪いので、誘いを断った。',['写真を断って撮った。','電車を断るで乗った。','部屋が断りに広い。'],'সময় না মেলায় নিমন্ত্রণ প্রত্যাখ্যান করেছি','断るপ্রস্তাব, অনুরোধ বা আমন্ত্রণ গ্রহণ না করা।誘いを断る প্রচলিত শব্দসংযোগ।'),
('選択','自分に合うコースを選択した。',['朝が選択を降った。','机を選択で眠った。','靴が選択を飲んだ。'],'নিজের উপযোগী কোর্স বেছে নিয়েছি','選択 কয়েকটি বিকল্প থেকে উপযুক্তটি বাছাই।コースを選択する এখানে যথার্থ কর্ম।'),
('募集','店では新しいアルバイトを募集している。',['お茶を募集で飲んだ。','靴が募集を走った。','駅に募集で寝た。'],'দোকানে নতুন কর্মী চাওয়া হচ্ছে','募集 একটি কাজ বা আয়োজনে লোক আহ্বান করা।アルバイトを募集する নিয়োগের জন্য আবেদনকারী চাওয়ার অর্থ।'),
('延期','大雨のため、試合は来週に延期された。',['鉛筆を延期で削った。','靴が延期を読んだ。','昨日は延期に寒かった。'],'বৃষ্টিতে খেলা পরের সপ্তাহে পেছানো হয়েছে','延期 আগে নির্ধারিত তারিখ পরে সরানো।試合を来週に延期する কারণ ও নতুন সময়সহ যথাযথ ব্যবহার।'),
('維持','毎日練習して、今の技術を維持している。',['維持のパンを焼いた。','友達が維持に雨だった。','電車を維持で食べた。'],'বর্তমান দক্ষতা ধরে রাখছি','維持 বর্তমান মান বা অবস্থা নষ্ট হতে না দিয়ে বজায় রাখা। অনুশীলনে技術維持 করা স্বাভাবিক।'),
('解決','話し合いによって、問題を解決した。',['ご飯を解決で眠った。','駅を解決に降った。','傘が解決を飲んだ。'],'আলোচনায় সমস্যা সমাধান করেছি','解決 সমস্যা বা বিরোধের সমাধান।問題を解決する সঠিক কর্ম ও শব্দসংযোগ।'),
('慣れる','新しい生活に少しずつ慣れてきた。',['パンを慣れて焼いた。','昨日が慣れるに雨だった。','机を慣れで読んだ。'],'নতুন জীবনে ধীরে অভ্যস্ত হচ্ছি','慣れる অপরিচিত অবস্থায় বারবার থাকার মাধ্যমে স্বাভাবিক বোধ করা।生活に慣れる-তে に অভ্যস্ত হওয়ার বিষয়।'),
('限る','この割引は学生に限る。',['水を限って飲み物だ。','机が限るで広い。','電車を限りに食べた。'],'ছাড় কেবল ছাত্রদের জন্য','に限るউপযোগিতা বা যোগ্যতার সীমা নির্ধারণ করে।割引は学生に限る মানে অন্যদের জন্য এই ছাড় নয়।'),
('防ぐ','窓を閉めて、雨が入るのを防いだ。',['写真を防いで写した。','昼ご飯を防ぐで食べた。','道が防ぎに晴れた。'],'বৃষ্টি ঢোকা ঠেকিয়েছি','防ぐ ক্ষতিকর বা অনাকাঙ্ক্ষিত ঘটনা ঘটতে না দেওয়া।雨が入るのを防ぐ ঠিক অর্থ।'),
('伝える','変更した時間を参加者に伝えた。',['靴を伝えて歩いた。','紙が伝えるで大きい。','朝ご飯を伝えに寝た。'],'অংশগ্রহণকারীদের বদলানো সময় জানিয়েছি','伝える কোনো তথ্য অন্যকে জানানো।情報を人に伝える-তে を তথ্য এবং に প্রাপক নির্দেশ করে।'),
('取り消す','旅行の予約を取り消した。',['料理を取り消して焼いた。','友達を取り消しで会った。','駅が取り消すに近い。'],'ভ্রমণের বুকিং বাতিল করেছি','取り消す আগের সিদ্ধান্ত বা নিবন্ধন বাতিল করা।予約を取り消す স্বাভাবিক ব্যবহার;延期 শুধু সময় পিছোয়।'),
('受け取る','配達員から荷物を受け取った。',['荷物に受け取って送った。','朝ご飯が受け取るで寒い。','机を受け取りに走った。'],'ডেলিভারির কর্মীর কাছ থেকে মালপত্র নিয়েছি','受け取る কারও দেওয়া বস্তু নিজের হাতে গ্রহণ।人から物を受け取る সঠিক কাঠামো।'),
]
for word,right,wrong,bn,reason in USAGE:vocab('n3',f'「{word}」の使い方として最もよいものを選んでください。',[right]+wrong,bn,reason)

# Reading and connected-text grammar are defined below.

def text(level,title,paragraph,items):
    passage='<h3>'+title+'</h3>'+''.join('<p>'+s+'</p>' for s in paragraph.split('\n'))
    for n,(opts,bn,reason) in enumerate(items,1):
        add(level,'grammar','文章文法',f'［{n}］に入る最もよいものを選んでください。',opts,0,bn,reason,passage=passage)

text('n5','週末の日記','土曜日、わたしは友だち［1］公園へ行きました。公園に大きい木が［2］。木の下で昼ご飯を食べました。天気がよくて、風も［3］です。日曜日は家で休みました。来週も公園へ［4］です。',[
(['と','を','が','から'],'বন্ধুর সঙ্গে','পাঠ্যে দুজন একসঙ্গে পার্কে গেছেন।人と কাজের সঙ্গী বোঝায়; এখানে と, বন্ধুর সঙ্গে।'),
(['ありました','いました','します','食べました'],'ছিল','গাছ প্রাণী বা মানুষ নয়, তাই অস্তিত্ব বোঝাতে ある। অতীত দিনের বিবরণে ありました, বড় গাছ ছিল।'),
(['気持ちがいい','気持ちをする','気持ちになる','気持ちといる'],'সুখকর','天気がよくて-এর পরে風-র অনুভূতি মূল্যায়ন। 気持ちがいい আরামদায়ক বা ভালো লাগে; দিনটি মনোরম।'),
(['行きたい','行いたい','行くたい','行ってたい'],'যেতে চাই','ইচ্ছা প্রকাশে 行きます-এর ます বাদ দিয়ে たい।楽しかった অভিজ্ঞতার পরে আবার যেতে চাইছেন।'),
])
text('n5','新しい部屋','わたしの新しい部屋は駅［1］近いです。前の部屋は駅から遠くて、学校まで一時間［2］。今は三十分です。部屋は少し小さいですが、明るいです。机を窓の近く［3］置きました。毎晩、そこで日本語を［4］います。',[
(['に','を','で','と'],'স্টেশনের কাছে','近い-এর তুলনা বা দূরত্বের কেন্দ্র に দিয়ে হয়।駅に近い স্টেশনের কাছে; কাজের স্থানので নয়।'),
(['かかりました','帰りました','終わりました','借りました'],'সময় লাগত','যাতায়াতে এক ঘণ্টা লাগার ক্রিয়া かかる। আগের ঘরের ঘটনা বলে かかりました অতীত রূপ।'),
(['に','を','から','と'],'জানালার কাছে','置く কোনো বস্তু একটি স্থানে রাখা; বস্তু机を এবং গন্তব্য窓の近くに। কাজের উদ্দেশ্য নয়, নির্দিষ্ট অবস্থান।'),
(['勉強して','勉強した','勉強する','勉強し'],'পড়ছি','দেওয়া末尾います-এর আগে て-রূপ লাগে।勉強しています নিয়মিত পড়াশোনার অভ্যাস বোঝায়।'),
])
text('n5','料理の時間','今日は母［1］いっしょに料理を作りました。先に野菜を洗って、［2］小さく切りました。料理は少し難しかった［3］、とてもおいしかったです。食べた後で、お皿を［4］。',[
(['と','が','を','から'],'মায়ের সঙ্গে','いっしょに-এর সঙ্গে人と সঙ্গী নির্দেশ করে। মায়ের সঙ্গে একসঙ্গে রান্না করার ঘটনা।'),
(['それから','でも','しかし','だから'],'তারপর','先に洗って-এর পরে切る, কাজের পরের ধাপ।それから সময়ের ক্রমে দুটি কাজ যুক্ত করে।'),
(['ですが','でしたから','ですよ','でしたね'],'ছিল তবে','শেষে ভালো স্বাদের বিপরীত মন্তব্য আসে।難しかったですが একটু কঠিন ছিল তবে ভালো হয়েছে; অতীত রূপই বিশেষণে আছে।'),
(['洗いました','洗いますか','洗いませんか','洗いたいです'],'ধুয়েছি','দিনের সম্পন্ন ঘটনাগুলো অতীতে বলা। খাওয়ার পরে বাসন ধোয়া শেষ কাজ হিসেবে洗いました যথাযথ।'),
])
text('n4','図書館のカード','引っ越したばかりなので、近所の図書館へ行きました。本を借りるにはカードが必要だ［1］。受付で申込書をもらい、名前と住所を書きました。住所が分かるものを見せる［2］、その日にカードを作ってもらえました。カードをなくさない［3］、財布に入れています。来週は日本語の本を借りて［4］と思います。',[
(['そうです','ようにです','そうなです','ためです'],'শুনেছি','受付ের নিয়ম শুনে জানা情報 দিচ্ছেন।普通形 + そうです এখানে伝聞, কার্ড প্রয়োজন বলে জানা গেছে।'),
(['と','ためを','ながらも','ままを'],'দেখালে','住所প্রমাণ দেখানোর পরে সঙ্গে সঙ্গে কার্ড তৈরি হয়েছে।見せると ওই শর্তের স্বাভাবিক ফল বোঝায়।'),
(['ように','ためで','ことが','そうで'],'যাতে না হারাই','নেতিবাচক目的 なくさないように ব্যবহার হয়। কার্ড না হারানোর জন্য財布-তে রাখার সচেতন ব্যবস্থা।'),
(['みよう','みるよう','みたところ','みながら'],'নিয়ে চেষ্টা করব','意向形 + と思う ভবিষ্যৎ ইচ্ছা।借りてみよう বই ধার করে দেখে নেওয়ার চেষ্টা বোঝায়।'),
])
text('n4','工場見学の準備','金曜日に工場を見学する［1］なりました。先生は歩きやすい靴を履いてくる［2］言いました。工場では写真を撮っては［3］そうです。説明を聞きながらメモを取れるように、ノートを持って［4］と思います。',[
(['ことに','ためで','ような','ものを'],'ঠিক হয়েছে','ことになる নিজের একার সিদ্ধান্তের বদলে নির্ধারিত পরিকল্পনা বোঝায়। শুক্রবার কারখানা দেখা হবে ঠিক হয়েছে।'),
(['ように','ためを','ところを','ものに'],'যেন পরে আসি','ように言う পরোক্ষ নির্দেশ। শিক্ষক সহজে হাঁটার জুতা পরে আসতে বলেছেন; কথাটি উদ্ধৃত না করে নির্দেশ দেওয়া।'),
(['いけない','いい','みたい','ある'],'অনুমতি নেই','てはいけない নিষেধ। কারখানায় ছবি তোলা অনুমোদিত নয়;末尾そうです নিয়মের শোনা খবর।'),
(['いこう','いった','いくなら','いっても'],'নিয়ে যাব','持っていこうと思います নিয়ে যাওয়ার ইচ্ছা।説明ের সময় মেমো নেওয়ার目的েノート সঙ্গে নেবেন।'),
])

text('n3','学習記録','日本語を勉強し始めたころ、私は新しい言葉を一日に三十個も覚えようとしていた。しかし、一週間後には半分以上を忘れてしまった。たくさん書けば覚えられる［1］ことに気付いた。\nそこで、毎日五個だけ選び、自分の生活に関係のある例文を作る［2］。数は減ったが、その言葉を使う機会が増えた［3］、前より長く覚えていられるようになった。\n今は、月末に記録を見直した［4］、翌月の計画を立てる。記録は点数を競うためのものではない。自分に合う方法を見つける［5］使っている。',[
(['わけではないという','はずだったという','ようにするという','ことにしたという'],'書いた量だけで覚えるとは限らない','数多く書けば必ず覚えられるという考えを否定している。わけではないが前の失敗とつながり、というで気付きの内容になる。'),
(['ことにした','ことになっていた','ところだった','ままだった'],'例文を書くことを決めた','前の方法を変えた本人の意思による決定。毎日五語の例文を作る新しい習慣はことにした。'),
(['おかげで','せいで','かわりに','くせに'],'使う機会が増えたおかげで','次の結果は長く記憶できるという望ましい変化。おかげで有益な原因を示し、失敗のせいでとは逆。'),
(['上で','うちに','一方で','ところに'],'記録を確認してから','見直した上では必要な確認を終えてから次の計画を立てる順序。記録の結果を次の計画に生かしている。'),
(['ために','とともに','につれて','かわりに'],'方法を見つけるために','記録を使う目的が自分に合う学習法の発見。意志的な目的の辞書形＋ためにが適切な表現である。'),
])
# Replace Japanese editorial review text above with Bengali translations below.
TEXT_BN_1=[
('অনেক লিখলেই মনে থাকবে এমন নয়','আগের ব্যর্থতায় বেশি লিখলে নিশ্চিত শেখা যায়—এই ধারণা নাকচ হয়েছে। わけではない অস্বীকার করে এবং という সেই উপলব্ধির বিষয়কে যুক্ত করে।'),
('সিদ্ধান্ত নিলাম','লেখক নিজে পদ্ধতি বদলে প্রতিদিন পাঁচটি শব্দ নিয়ে উদাহরণ লেখার সিদ্ধান্ত নেন। 自分の সিদ্ধান্তের জন্য ことにした।'),
('সুযোগ বাড়ার কল্যাণে','নতুন শব্দ ব্যবহারের সুযোগ বেড়ে বেশি দিন মনে থাকছে—ইতিবাচক ফল। উপকারী কারণের おかげで প্রয়োজন, নেতিবাচকせいで নয়।'),
('পর্যালোচনা করে তারপর','আগেররেকর্ড ভালোভাবে দেখে পরের মাসের পরিকল্পনা। た上で প্রয়োজনীয় প্রথম ধাপ শেষ করে পরের কাজের সচেতন ক্রম বোঝায়।'),
('পদ্ধতি খুঁজে পাওয়ার জন্য','রেকর্ড রাখা স্কোরের প্রতিযোগিতা নয়, নিজের উপযোগী শেখার পদ্ধতি খোঁজার উদ্দেশ্যে।辞書形 + ために উদ্দেশ্য প্রকাশ।'),
]
for q,(b,e) in zip(BANK['n3'][-5:],TEXT_BN_1):q['review']={'answerBn':b,'explanationBn':e}

text('n3','地域の道具庫','私の町では、たまにしか使わない工具を共同で管理することになった。個人で買う［1］、道具庫から借りれば、場所もお金も節約できる。\n利用者が増える［2］、返却の遅れも増えてきた。そこで、借りる日数を最初に登録する仕組みにした。返却が遅れる場合は、必ず連絡する［3］。\nこの仕組みを始めた［4］、遅れがなくなったわけではない。しかし、次の人の予定が分かるようになり、問題を話し合いやすくなった。規則を増やすだけでなく、情報を共有することが大切だ［5］。',[
(['かわりに','最中に','うちに','たびに'],'নিজে কেনার পরিবর্তে','নিয়মিত লাগে না এমন যন্ত্র নিজে না কিনে ধার নেওয়ার বিকল্প।辞書形 + かわりに দুই কাজের বদল বোঝায়।'),
(['につれて','にしては','に限って','をはじめ'],'বাড়ার সঙ্গে সঙ্গে','ব্যবহারকারী সংখ্যা বাড়ার সঙ্গে返却বিলম্ব বাড়ছে।に連れて সমান্তরাল পরিবর্তনের ধারা।'),
(['ことになっている','つもりでいる','ところである','わけにはいかない'],'নিয়ম ঠিক আছে','বিলম্ব হলে যোগাযোগ করতে হবে—সবার জন্য নির্ধারিত নিয়ম।ことになっている প্রতিষ্ঠিত নিয়ম বোঝায়।'),
(['からといって','ためには','ようにして','ことからだけ'],'শুরু করেছি বলেই','নতুন ব্যবস্থার ফলে সব বিলম্ব বন্ধ হয়েছে এমন নয়।からといって〜わけではない কারণ থেকে নিশ্চিত ফল টানা অস্বীকার।'),
(['と考えている','ことに見える','に気がする','ように知っている'],'মনে করি','আগের ঘটনাগুলো দেখে নিজের সিদ্ধান্তের বক্তব্য।大切だと考えている উদ্ধৃতিと দিয়ে মত প্রকাশ করে।'),
])
text('n3','写真展の案内','文化館で写真展を開く準備をしている。作品を並べるだけでは、見た人に撮影した理由が伝わらない［1］。そこで、写真の横に短い説明を付けることにした。\n長い説明を書けばよい［2］。写真を見る時間がなくなるほどの文章は、かえって読みにくい。撮った場所やそのときの気持ちなど、必要な内容に［3］つもりだ。\n来場者の年齢［4］、分かりやすい言葉を選ぶ必要もある。写真を楽しんでもらうために、準備を十分にした［5］、会場を開けたい。',[
(['かもしれない','ことにした','ためにする','つもりだった'],'হয়তো বোঝা যাবে না','শুধু ছবি সাজালে দর্শক撮影ের理由 না বুঝতে পারেন—অনিশ্চিত সম্ভাবনা।かもしれない এই আশঙ্কা প্রকাশ।'),
(['わけではない','はずがある','ところである','に決まっている'],'লম্বা হলেই ভালো নয়','পরের বাক্যে অতিদীর্ঘ লেখা পড়তে অসুবিধা বলে।わけではない দীর্ঘ লেখা নিশ্চিত ভালো—এমন সাধারণ ধারণা নাকচ করে।'),
(['絞る','流れる','広がる','通う'],'সীমাবদ্ধ করব','必要な内容に絞る কেবল প্রয়োজনীয় তথ্য নির্বাচন করে সীমা রাখা। ব্যাখ্যা ছোট ও সহজ রাখার প্রসঙ্গ।'),
(['によって','にとって','につれて','を通して'],'বয়স অনুযায়ী','দর্শকের বয়সভেদে উপযুক্ত ভাষা ভিন্ন হতে পারে।によって পার্থক্যের ভিত্তি বোঝায়।'),
(['上で','うちに','かわりに','最中に'],'ভালোভাবে প্রস্তুতি শেষ করে','た上で প্রথমে প্রস্তুতি সম্পন্ন করে তারপর খুলতে চান। পর্যাপ্ত প্রস্তুতি会場খোলার আগের প্রয়োজনীয় ধাপ।'),
])
text('n3','働き方を考える','以前の私は、仕事の連絡が来る［1］、夜でもすぐ返事をしていた。早く答える人ほど仕事ができると思っていたからだ。しかし、睡眠が足りず、翌日の説明で間違えることが増えた。\nそこで、急ぎでないメールには朝返事をする［2］。夜に休む時間ができ、仕事に集中しやすくなった。返事が遅くなった［3］、説明の内容は前より正確になった。\nもちろん、緊急の連絡を無視する［4］。急ぎかどうかの判断をチームで共有している。速さだけで人の働きを決める［5］と思う。',[
(['たびに','うちに','かわりに','ところに'],'প্রতিবার','連絡এসে যাওয়ার প্রতিবার রাতেও উত্তর দিতেন।辞書形 + たびに পুনরাবৃত্তির প্রতিটি ঘটনার সঙ্গে কাজ বোঝায়।'),
(['ことにした','ことになっていた','ところだった','最中だった'],'নিজে সিদ্ধান্ত নিলাম','লেখক আগের সমস্যা দেখে নিজের কাজের নিয়ম বদলেছেন।নিজের সিদ্ধান্তের ことにした যথাযথ।'),
(['ものの','ために','おかげで','に比べて'],'যদিও','জবাব ধীর হওয়া স্বীকার করেও ব্যাখ্যা উন্নত হওয়ার বিপরীত ফল।ものの আনুষ্ঠানিকভাবে যদিও বা তবুও।'),
(['わけではない','に違いない','ようにした','こともないとは限らない'],'উপেক্ষা করছি এমন নয়','জরুরি যোগাযোগ অবশ্যই দেখা হয়, তাই休息মানেসব連絡উপেক্ষা—এই ধারণা নাকচ।わけではない আংশিক অস্বীকার।'),
(['べきではない','ことにする','ところにある','ようになっている'],'বিচার করা উচিত নয়','উপসংহার মূল্যায়নের পরামর্শ: শুধু速度দিয়ে職務ক্ষমতা নির্ধারণ অনুচিত।辞書形 + べきではない প্রয়োজনীয় নেতিবাচক পরামর্শ।'),
])
text('n3','自転車の共同利用','駅前の自転車を共同で使うサービスが始まった。登録すると、一時間だけ借りられる。買い物へ行く［1］、健康のために短い距離を走る人もいる。\n利用の［2］、ライトやタイヤを確認する必要がある。壊れていたら、使わずに係員へ知らせる。安全を守るために、自分で確かめることも大切だ。\n便利になった［3］、全員が利用できるわけではない。登録には本人確認が必要で、十五歳未満の子供は使えない。利用者の希望に［4］、大きさの違う自転車も増やしていく予定だ。\nこのサービスを［5］、町の移動方法を少しずつ変えていきたい。',[
(['だけでなく','わけがなく','こともなく','しかなく'],'শুধু কেনাকাটা নয়','শুধু কেনাকাটা নয়, স্বাস্থ্যের জন্য অল্প পথ চলার ব্যবহারও যোগ হচ্ছে। だけでなく একটি উদ্দেশ্যের সঙ্গে আরেকটি উদ্দেশ্য যুক্ত করে।'),
(['際に','うちで','わりと','ままで'],'ব্যবহারের সময়ে','名詞の際に কোনো কাজের সময় বা উপলক্ষ বোঝায়। সাইকেল ব্যবহার শুরুর সময় লাইট ও টায়ার পরীক্ষা করতে হবে বলা হচ্ছে।'),
(['とはいえ','によって','からこそ','おかげで'],'সুবিধা হয়েছে বটে তবে','সুবিধা হয়েছে স্বীকার করেও সবার যোগ্যতা নেই বলা হচ্ছে। とはいえ আগের সত্যের সীমা দেখিয়ে বিপরীত তথ্য আনে।'),
(['応じて','関して','比べて','対しても'],'চাহিদা অনুযায়ী','希望に応じて মানুষের চাহিদা অনুযায়ী ব্যবস্থা বদলানো। নানা মাপের সাইকেল বাড়ানো ব্যবহারকারীর প্রয়োজনের সঙ্গে সামঞ্জস্য করে।'),
(['通して','めぐって','こめて','もとづいて'],'মাধ্যমে','を通して কোনো ব্যবস্থা বা অভিজ্ঞতার মাধ্যমে লক্ষ্য অর্জন। ভাগাভাগি সাইকেল ব্যবস্থার মাধ্যমে শহরের যাতায়াত বদলাতে চান।'),
])
text('n3','発表の練習','初めて研究会で発表することになった。何度も原稿を読んだ［1］、時間内に話せなかった。言いたいことを全部入れようとして、説明が長くなっていたのだ。\nそこで、友人の意見に［2］、内容を三つに分けた。一つの話題が終わるたびに結論を短く示した。原稿を減らした［3］、聞く人にとって分かりやすくなった。\n本番で緊張しない［4］、会場と同じ広さの部屋で練習した。練習を重ねる［5］、自然な速さで話せるようになった。',[
(['にもかかわらず','おかげで','ために','ことから'],'বারবার পড়া সত্ত্বেও','বহুবার পড়েছেন, অথচ নির্দিষ্ট সময়ের মধ্যে বলতে পারেননি। にもかかわらず প্রত্যাশার বিপরীত ফল, সত্ত্বেও, প্রকাশ করে।'),
(['基づいて','つれて','とって','限って'],'মতের ভিত্তিতে','に基づいて কোনো তথ্য বা মতের ভিত্তিতে কাজ। বন্ধুর পরামর্শকে ভিত্তি করে বক্তব্য তিন অংশে সাজিয়েছেন।'),
(['結果','最中','一方','ところを'],'ফল হিসেবে','原稿減らした結果 বক্তব্য কমানোর ফলে সহজবোধ্য হয়েছে। た結果 একটি কাজের পরে দেখা ফল নির্দেশ করে।'),
(['ように','ためで','ことが','そうで'],'যাতে না নার্ভাস হই','緊張しないように নঞর্থক উদ্দেশ্য, যাতে উদ্বিগ্ন না হই। প্রকৃত স্থানের মতো ঘরে অনুশীলন সেই পরিস্থিতি প্রতিরোধের জন্য।'),
(['につれて','に限って','にしては','に対して'],'অভ্যাস বাড়ার সঙ্গে','অনুশীলন বাড়ার সঙ্গে স্বাভাবিক গতিতে বলতে শিখেছেন। に連れて দুটি সমান্তরাল পরিবর্তনের ধারা প্রকাশ করে।'),
])

def reading(level,kind,title,paragraph,items):
    passage='<h3>'+html.escape(title)+'</h3>'+''.join('<p>'+s+'</p>' for s in paragraph.split('\n'))
    for prompt,opts,bn,reason in items:
        add(level,'reading','読解',prompt,opts,0,bn,reason,passage=passage,reading_kind=kind)

reading('n5','mid','友だちへのメール','ミナさんへ\nあした、いっしょに美術館へ行きませんか。美術館は十時に開きますから、九時半に駅の前で会いましょう。駅からバスで二十分です。昼ご飯は美術館のとなりの店で食べたいです。私は午後三時からアルバイトがありますから、二時までに駅に帰ります。\nサラ',[
('二人は何時に会いますか。',['九時半','十時','二時','三時'],'সাড়ে নয়টায়','美術館দশটায় খুললেও দেখা করার সময় 九時半। স্টেশনের সামনে সাড়ে নয়টায় দেখা করে বাসে যাবেন।'),
('サラさんはどうして二時までに駅に帰りますか。',['三時からアルバイトがあるから','美術館が二時に閉まるから','昼ご飯を食べないから','バスがないから'],'তিনটা থেকে কাজ আছে বলে','শেষে三時からアルバイトがありますから বলা। কাজ শুরুর আগেই ফিরতে চান; জাদুঘর বন্ধ হওয়ার সময় বলা হয়নি।'),
])
reading('n5','mid','パンの店','家の近くに小さいパンの店ができました。朝七時から夜六時まで開いています。私はいつも学校へ行く前に、そこでパンを一つ買います。百五十円です。日曜日は休みですから、その日は母が朝ご飯を作ります。店の前にいすがありますが、店の中では食べられません。',[
('この人はいつパンを買いますか。',['学校へ行く前','学校から帰った後','夜六時の後','日曜日の朝'],'স্কুলে যাওয়ার আগে','学校へ行く前にそこでパンを一つ買います সরাসরি বলা। দোকান সকাল সাতটায় খোলে বলে যাওয়ার আগে কেনা সম্ভব।'),
('日曜日の朝ご飯はどうしますか。',['母が作ります','この店で食べます','何も食べません','学校で買います'],'মা বানান','দোকান রবিবার বন্ধ। その日は母が朝ご飯を作ります অনুযায়ী ওইদিন বাড়িতে মায়ের তৈরি খাবার খায়।'),
])
reading('n5','mid','バスで学校へ','きょうは雨です。いつも学校まで自転車で行きますが、きょうはバスで行きました。家の近くのバス停から八時に乗りました。学校まで三十分かかりました。授業は九時に始まりますから、少し時間がありました。学校で友だちと話してから、教室へ入りました。',[
('きょうは何で学校へ行きましたか。',['バス','自転車','電車','車'],'বাসে','いつもসাইকেল, কিন্তুきょうবৃষ্টি বলে বাস। প্রশ্ন আজকের যাতায়াত জানতে চায়, নিয়মিত অভ্যাস নয়।'),
('学校に着いたのは何時ですか。',['八時半','八時','九時','九時半'],'সাড়ে আটটায়','বাসে উঠেছেন আটটায় এবং ত্রিশ মিনিট লেগেছে। আটটার সঙ্গে ত্রিশ মিনিট যোগ করলে আটটা ত্রিশ।'),
])
reading('n5','mid','家族の昼ご飯','先週の日曜日、父と母と弟と私で料理を作りました。父は魚を焼きました。母はスープを作りました。私と弟は野菜を洗って、サラダを作りました。十二時にみんなで食べました。魚が少し多かったですから、残りは夜に食べました。家族で料理を作るのは楽しかったです。',[
('サラダを作ったのはだれですか。',['私と弟','父と母','母だけ','弟と父'],'লেখক ও ছোট ভাই','私と弟は野菜を洗って、サラダを作りました। বাবা মাছ এবং মা স্যুপ বানিয়েছেন; কাজগুলো আলাদা।'),
('夜に何を食べましたか。',['昼に残った魚','新しく作ったサラダ','店で買ったスープ','何も食べませんでした'],'দুপুরের অবশিষ্ট মাছ','মাছ একটু বেশি ছিল বলে残りは夜に食べました। নতুন কেনা বা নতুন করে রান্নার কথা নেই।'),
])
reading('n5','mid','図書館の土曜日','土曜日は朝から図書館へ行きました。図書館で日本語の本を読みました。私は辞書を持っていませんでしたが、図書館の辞書を使いました。昼ご飯を食べる店は図書館の近くにありませんから、家からパンを持ってきました。午後一時に外のベンチでパンを食べて、また図書館へ入りました。',[
('どこの辞書を使いましたか。',['図書館の辞書','自分の辞書','友だちの辞書','店の辞書'],'পাঠাগারের অভিধান','লেখকের নিজের অভিধান সঙ্গে ছিল না। 図書館の辞書を使いました বলে পাঠাগারের অভিধান ব্যবহার করেছেন।'),
('パンはどこで食べましたか。',['図書館の外のベンチ','図書館の中','近くの店','自分の家'],'পাঠাগারের বাইরে বেঞ্চে','রুটি বাড়ি থেকে এনেছেন, কিন্তু খেয়েছেন外のベンチで。 কোথা থেকে এনেছেন ও কোথায় খেয়েছেন আলাদা তথ্য।'),
])
reading('n5','mid','赤いノート','昨日、学校でノートがありませんでした。机の中やかばんの中を見ましたが、ありませんでした。先生に聞くと、先生の机に赤いノートがありました。私の名前が書いてありました。前の日、宿題を先生に見せて、ノートを持って帰りませんでした。先生にお礼を言って、ノートをもらいました。',[
('ノートはどこにありましたか。',['先生の机','自分のかばん','自分の机の中','家の部屋'],'শিক্ষকের টেবিলে','নিজের টেবিল ও ব্যাগে পাওয়া যায়নি, পরে先生の机に赤いノートがありました। শেষ পাওয়া অবস্থানটাই উত্তর।'),
('どうして先生のところにノートがありましたか。',['宿題を見せた後、持って帰らなかったから','先生が新しく買ったから','友だちが赤くしたから','名前を書かなかったから'],'বাড়ির কাজ দেখিয়ে ফেরত নেননি বলে','前の日宿題を先生に見せて持って帰らなかった বলে আগের দিনের ফেলে যাওয়াই কারণ। নাম লেখা ছিল বলে নিজেরটি চিনেছেন।'),
])

N5_NOTICES=[
('写真の教室','土曜日　午後一時から三時\n場所：市民センター二階\n持ってくるもの：カメラ\nノートと鉛筆はこちらにあります。','何を持っていきますか。',['カメラだけ','カメラとノート','鉛筆だけ','何も持っていきません'],'শুধু ক্যামেরা','আনতে বলা তালিকায় কেবল ক্যামেরা। খাতা ও পেন্সিল কেন্দ্রে আছে, তাই সেগুলো সঙ্গে লাগবে না।'),
('店の休み','この店は毎週火曜日が休みです。\n今週だけ、水曜日も休みます。月曜日と木曜日は午前九時から開きます。','今週、休みの日はいつですか。',['火曜日と水曜日','月曜日と火曜日','水曜日と木曜日','木曜日だけ'],'মঙ্গল ও বুধবার','প্রতি মঙ্গলবারের ছুটি বজায় আছে; শুধু এ সপ্তাহে বুধবারও বন্ধ। নতুন অতিরিক্ত ছুটি নিয়মিত ছুটির সঙ্গে যোগ হবে।'),
('お弁当の注文','お弁当は一つ五百円です。注文は朝十時までです。\n電話で注文してください。昼十二時にこの店で受け取ってください。','お弁当はどこでもらいますか。',['この店','家','学校','駅'],'এই দোকানে','নোটিশে十二時にこの店で受け取ってください বলা। ফোনে注文করলেও পৌঁছে দেওয়ার কথা নেই, দোকান থেকে নিতে হবে।'),
('学校の旅行','集合：学校の前、午前八時\n出発：午前八時半\n持ち物：昼ご飯、飲み物\n帰る時間：午後四時','何時に集まりますか。',['午前八時','午前八時半','午後四時','午後八時'],'সকাল আটটায়','集合 জড়ো হওয়ার সময় আটটা। আটটা ত্রিশ出発বাসছাড়ার সময়, প্রশ্ন একত্র হওয়ার সময় নিয়ে।'),
('映画館のお知らせ','午前の映画：十時から十二時\n午後の映画：二時から四時\nチケット：大人八百円、子供四百円','午後の映画は何時に終わりますか。',['四時','二時','十時','十二時'],'চারটায়','দুপুরের সিনেমার সময় দুইটা থেকে চারটা। শুরু二時, শেষ四時; সকালের সময় আলাদা।'),
('図書館の本','本は一人三冊まで、二週間借りられます。\n雑誌は図書館の中だけで読んでください。\n辞書も持って帰れません。','家に持って帰れるものは何ですか。',['本','雑誌','辞書','雑誌と辞書'],'বই','বই তিনটি পর্যন্ত ধার নেওয়া যায়। পত্রিকা ও অভিধান শুধু ভেতরে ব্যবহারের জন্য, বাড়ি নেওয়া নিষেধ।'),
('プールの時間','月曜日から金曜日：午後一時から八時\n土曜日：午前十時から午後六時\n日曜日：休み','土曜日は何時から入れますか。',['午前十時','午後一時','午後六時','午後八時'],'সকাল দশটা থেকে','শনিবারের আলাদা সময় সকাল দশটা থেকে সন্ধ্যা ছয়টা। সপ্তাহের অন্য দিনের একটার সময় শনিবারে প্রযোজ্য নয়।'),
]
